if (itens && !Array.isArray(itens) && typeof itens === "object") {
  // agente pode mandar { itens: [...] } embrulhado
  if (Array.isArray(itens.itens)) itens = itens.itens;
  else itens = [itens]; // ou um item único como objeto
}
if (!Array.isArray(itens) || itens.length === 0) {
  return [{ json: { ok:false, erro:"nenhum item recebido. Envie 'itens' como uma lista: placas com material/tipo/medidas/quantidade e itens de catálogo com produto/quantidade." } }];
}

const clienteNome = String(entrada.cliente_nome || "").trim();
if (!clienteNome) {
  return [{ json: { ok:false, erro:"faltou o nome do cliente (cliente_nome)." } }];
}
const clienteTelefone  = String(entrada.cliente_telefone  || "").trim();
