// ============================ CÁLCULO DOS ITENS =============================
const linhas = [];
let totalGeral = 0;

for (let i = 0; i < itens.length; i++) {
  const it = itens[i] || {};

  if (it.produto) {
    // ------- item de catálogo (Tabela 2026) -------
    const r = calcularPrecoItem({
      produto: it.produto,
      quantidade: it.quantidade,
      largura: it.largura,
      altura: it.altura,
    });
    if (!r.ok) {
      const erro = r.usar_placa
        ? `item ${i + 1}: é placa personalizada — reenvie este item no formato de placa (material, tipo, largura, altura, quantidade), sem o campo 'produto'.`
        : `item ${i + 1}: ${r.erro}`;
      return [{ json: { ok:false, erro } }];
    }
    const descricao = String(it.descricao || r.nome).trim();
    linhas.push({
      n: i + 1, descricao,
      caracteristicas: specsItem(r.produto, r),
      quantidade: r.quantidade, unitario: r.unitario, total: r.total,
      resumoTxt: `${r.quantidade}x ${r.nome} = ${brl(r.total)}`,
    });
    totalGeral += r.total;
  } else {
    // ------- placa personalizada -------
    const r = calcularPrecoPlaca({
      material: it.material,
      tipo: it.tipo,
      largura: it.largura,
      altura: it.altura,
      quantidade: it.quantidade,
      placaEndereco: !!it.placa_endereco,
    }, { exigirEspessuraPvc: true });
    if (!r.ok) {
      return [{ json: { ok:false, erro:`item ${i + 1}: ${r.erro}` } }];
    }
    if (!r.dentro_do_limite) {
      return [{ json: { ok:false, erro:`item ${i + 1} (${r.material} ${r.altura_cm}x${r.largura_cm} cm) excede a chapa padrão. Encaminhe para um atendente humano (ferramenta transferir).` } }];
    }
    if (r.quantidade > 20) {
      return [{ json: { ok:false, erro:`item ${i + 1}: quantidade acima de 20 unidades de placa. Encaminhe para um atendente humano (ferramenta transferir).` } }];
    }
    const descricao = String(it.descricao || `Placa de ${r.material}`).trim();
    linhas.push({
      n: i + 1, descricao,
      caracteristicas: [
        "Forma: retangular",
        `Material: ${r.materialDesc}`,
        `Acabamento: ${r.tipo}`,
        `Dimensões: ${fmtDim(r.altura_cm)} x ${fmtDim(r.largura_cm)} cm (A x L)`,
      ],
      quantidade: r.quantidade, unitario: r.unitario, total: r.total,
      resumoTxt: `${r.quantidade}x ${descricao} (${r.material} ${r.tipo}, ${r.altura_cm}x${r.largura_cm} cm) = ${brl(r.total)}`,
    });
    totalGeral += r.total;
  }
}
totalGeral = round2(totalGeral);

// ============================ NÚMERO / DATA =================================
